<?= $this->extend(ADMIN_VIEW.'layout') ?><?= $this->section('main-content') ?><main class="dashboard-container"><div class="page-heading d-flex justify-content-between align-items-start flex-wrap"><div><div class="page-eyebrow">Shopify / AI Analysis</div><h1 class="h3 mb-1">Callback requests</h1><p class="text-muted mb-0">Requests are linked to their Hair or Skin Analysis lead and must be treated as high priority.</p></div><a class="btn btn-outline-primary" href="<?= base_url('admin/integrations/shopify/ai-hair-analysis/leads') ?>">Analysis leads</a></div><?php if(!empty($migrationRequired)): ?><div class="alert alert-warning">Run <code>php spark migrate</code> before viewing callback requests.</div><?php endif; ?><section class="card shadow-sm"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Priority</th><th>Analysis</th><th>Customer</th><th>Preferred time</th><th>Note</th><th>Status</th><th>Received</th></tr></thead><tbody><?php foreach($requests as $request): ?><tr class="<?= $request['priority']==='high'?'table-warning':'' ?>"><td><span class="badge badge-danger">HIGH</span></td><td><strong><?= esc(strtoupper((string)$request['analysis_type'])) ?></strong><br><code><?= esc($request['lead_reference']) ?></code></td><td><?= esc($request['shopify_customer_id']) ?><br><small><?= esc($request['store_domain']) ?></small></td><td><?= esc((string)($request['preferred_time']??'—')) ?></td><td><?= esc((string)($request['note']??'—')) ?></td><td><?= esc(ucwords(str_replace('_',' ',(string)$request['status']))) ?></td><td><?= esc((string)($request['created_at']??'—')) ?></td></tr><?php endforeach; ?><?php if($requests===[]): ?><tr><td colspan="7" class="text-center text-muted py-4">No callback requests.</td></tr><?php endif; ?></tbody></table></div></section></main><?= $this->endSection() ?>
